import { registerWebComponents } from '@domg-wc/common';
import { VlRadioComponent, VlRadioGroupComponent } from '@domg-wc/components/form';

registerWebComponents([VlRadioComponent, VlRadioGroupComponent]);

// vl-change komt van de vl-radio die aangevinkt wordt en bubbelt naar de groep; event.detail.value is zijn value.
document.querySelector('#land-zee').addEventListener('vl-change', (event) => {
    console.log(event.detail.value);
});
